"use client";

import { MotionConfig, motion, useReducedMotion } from "motion/react";
import {
	type CSSProperties,
	type ReactNode,
	useEffect,
	useRef,
	useState,
} from "react";

import "./hero-03.css";

import Header from "./header";
import { CheckIcon, CopyIcon, TentUiMark } from "./icons";

const BACKGROUND_IMAGE =
	"https://raw.githubusercontent.com/swamimalode07/rare-ui/main/public/assets/landing/herobg.webp";
const GITHUB_URL = "https://github.com/sourabhs701/tentui.com";
const INSTALL_COMMAND = "npx shadcn add @tentui/animated-tabs";
const CTA_SPRING = { type: "spring", stiffness: 300, damping: 22 } as const;

const join = (...classes: Array<string | false | null | undefined>) =>
	classes.filter(Boolean).join(" ");

function StretchBackground({
	active,
	className,
}: {
	active: boolean;
	className: string;
}) {
	const reduceMotion = useReducedMotion();

	return (
		<motion.div
			animate={{
				left: active && !reduceMotion ? -9 : 0,
				right: active && !reduceMotion ? -9 : 0,
			}}
			className={join("absolute inset-y-0", className)}
			initial={false}
			style={{ cornerShape: "squircle" } as CSSProperties}
			transition={reduceMotion ? { duration: 0 } : CTA_SPRING}
		/>
	);
}

function CopyCommandButton({ children }: { children: ReactNode }) {
	const [copied, setCopied] = useState(false);
	const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

	useEffect(
		() => () => {
			if (timeoutRef.current) clearTimeout(timeoutRef.current);
		},
		[],
	);

	const copy = async () => {
		try {
			await navigator.clipboard.writeText(INSTALL_COMMAND);
			setCopied(true);
			if (timeoutRef.current) clearTimeout(timeoutRef.current);
			timeoutRef.current = setTimeout(() => setCopied(false), 1500);
		} catch {
			setCopied(false);
		}
	};

	const iconLayer = "col-start-1 row-start-1 block size-full [&>svg]:size-full";

	return (
		<button
			aria-label={copied ? "Copied" : "Copy command"}
			className="relative flex h-12 max-w-full flex-row-reverse items-center justify-center gap-2 rounded-2xl pr-4 pl-4 text-white/50 transition-colors hover:text-white focus-visible:outline-2 focus-visible:outline-white/70 sm:pl-5"
			onClick={copy}
			type="button"
		>
			<span className="grid size-3.5 place-items-center">
				<motion.span
					animate={{
						opacity: copied ? 0 : 1,
						scale: copied ? 0.6 : 1,
						filter: copied ? "blur(3px)" : "blur(0px)",
					}}
					className={iconLayer}
					initial={false}
					transition={{ duration: 0.15, ease: "easeIn" }}
				>
					<CopyIcon />
				</motion.span>
				<motion.span
					animate={{
						opacity: copied ? 1 : 0,
						scale: copied ? 1 : 0.6,
						filter: copied ? "blur(0px)" : "blur(3px)",
					}}
					className={join(iconLayer, "text-(--hero-accent)")}
					initial={false}
					transition={{
						opacity: { duration: 0.14, delay: copied ? 0.08 : 0 },
						filter: { duration: 0.14, delay: copied ? 0.08 : 0 },
						scale: {
							type: "spring",
							stiffness: 520,
							damping: 17,
							delay: copied ? 0.08 : 0,
						},
					}}
				>
					<CheckIcon />
				</motion.span>
			</span>
			{children}
		</button>
	);
}

function HeroCta() {
	const reduceMotion = useReducedMotion();
	const [hovered, setHovered] = useState<"command" | "cta" | null>(null);
	const shift = (value: number) => (reduceMotion ? 0 : value);

	return (
		<div className="mt-4 flex flex-wrap items-center justify-center gap-3">
			<motion.div
				animate={{ x: hovered === "cta" ? shift(-9) : 0 }}
				className="relative max-w-full"
				initial={false}
				onMouseEnter={() => setHovered("command")}
				onMouseLeave={() => setHovered(null)}
				transition={reduceMotion ? { duration: 0 } : CTA_SPRING}
			>
				<StretchBackground
					active={hovered === "command"}
					className="bg-neutral-900"
				/>
				<CopyCommandButton>
					<code className="overflow-x-auto whitespace-nowrap font-mono font-semibold text-white text-xs sm:text-sm">
						npx shadcn add @tentui
						<span className="font-normal text-white/50">/animated-tabs</span>
					</code>
				</CopyCommandButton>
			</motion.div>

			<motion.div
				animate={{ x: hovered === "command" ? shift(9) : 0 }}
				className="group relative"
				initial={false}
				onMouseEnter={() => setHovered("cta")}
				onMouseLeave={() => setHovered(null)}
				transition={reduceMotion ? { duration: 0 } : CTA_SPRING}
			>
				<StretchBackground
					active={hovered === "cta"}
					className="bg-(--hero-accent) transition-colors duration-150 ease-out group-hover:bg-(--hero-accent-hover)"
				/>
				<a
					className="relative flex h-12 items-center rounded-2xl px-6 font-semibold text-sm text-white [font-family:var(--hero-font)] focus-visible:outline-2 focus-visible:outline-white/70"
					href="/docs"
				>
					Quick Start
				</a>
			</motion.div>
		</div>
	);
}

export type Hero03Props = {
	backgroundImageSrc?: string;
	brandName?: string;
	currentPath?: string;
	githubUrl?: string;
	starCount?: number | string | null;
};

export default function Hero03({
	backgroundImageSrc = BACKGROUND_IMAGE,
	brandName = "Tent UI",
	currentPath = "/",
	githubUrl = GITHUB_URL,
	starCount = "1.2k",
}: Hero03Props = {}) {
	return (
		<MotionConfig reducedMotion="user">
			<section className="hero-03 relative w-full bg-background p-1.5 md:p-2.5">
				<Header
					brandName={brandName}
					currentPath={currentPath}
					githubUrl={githubUrl}
					starCount={starCount}
				/>
				<div
					className="relative flex min-h-[calc(100svh-0.75rem)] w-full items-center justify-center overflow-hidden rounded-[45px] md:min-h-[calc(100svh-1.25rem)]"
					style={{ cornerShape: "squircle" } as CSSProperties}
				>
					<img
						alt=""
						aria-hidden="true"
						className="pointer-events-none absolute inset-0 size-full rounded-[inherit] object-cover"
						src={backgroundImageSrc}
					/>
					<div className="pointer-events-none absolute inset-0 rounded-[inherit] bg-linear-to-t from-6% from-background to-transparent" />
					<div className="relative mx-auto flex w-full max-w-6xl flex-col items-center justify-center gap-3 px-4 pt-24 pb-32 text-center sm:gap-4 sm:px-6">
						<div className="flex items-center gap-2 rounded-full bg-white/35 py-1.5 pr-3.5 pl-4 backdrop-blur-xl dark:bg-neutral-950/30">
							<span className="font-medium text-black text-sm [font-family:var(--hero-font)] dark:text-white">
								Free &amp; open source
							</span>
							<span className="h-4 w-px bg-black/15 dark:bg-white/20" />
							<a
								className="flex items-center gap-1.5 rounded-full font-semibold text-black text-sm [font-family:var(--hero-font)] focus-visible:outline-2 focus-visible:outline-black/60 dark:text-white dark:focus-visible:outline-white/70"
								href={githubUrl}
								rel="noreferrer"
								target="_blank"
							>
								<TentUiMark className="h-4 w-auto text-(--hero-accent)" />
								MIT licensed
							</a>
						</div>
						<h1 className="max-w-4xl text-balance font-bold text-4xl text-black tracking-tight [font-family:var(--hero-font)] sm:text-5xl md:text-6xl lg:text-7xl dark:text-white">
							Tasteful Components, Made to Stand Out.
						</h1>
						<p className="max-w-xl font-medium text-black/80 sm:text-lg dark:text-white/80">
							A collection of polished, animated components. Browse them in
							action and install any component with the shadcn CLI.
						</p>
						<HeroCta />
					</div>
				</div>
			</section>
			<section className="hero-03 relative w-full h-400px bg-background p-1.5 md:p-2.5">

			</section>
		</MotionConfig>
	);
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { Fragment, useEffect, useId, useState } from "react";

import {
	ContrastIcon,
	GithubIcon,
	SparkleIcon,
	StarIcon,
	TentUiMark,
} from "./icons";

const NAV_LINKS = [
	{ label: "Home", href: "/" },
	{ label: "Components", href: "/components" },
] as const;

const NAV_PILL =
	"rounded-full bg-neutral-900 shadow-[inset_0_0_0_1px_rgb(255_255_255/0.07),inset_0_1px_0_0_rgb(80_80_80/0.30),inset_0_-1px_0_0_rgb(0_0_0/0.3)]";
const MORPH_SPRING = { type: "spring", stiffness: 250, damping: 24 } as const;
const POP_SPRING = { type: "spring", stiffness: 320, damping: 15 } as const;
const LAYOUT_SPRING = {
	type: "spring",
	stiffness: 300,
	damping: 30,
} as const;

const join = (...classes: Array<string | false | null | undefined>) =>
	classes.filter(Boolean).join(" ");

function ThemeButton({ className }: { className?: string }) {
	const toggleTheme = () => {
		const root = document.documentElement;
		const nextTheme = root.classList.contains("dark") ? "light" : "dark";
		root.classList.toggle("dark", nextTheme === "dark");
		root.style.colorScheme = nextTheme;
		localStorage.setItem("theme", nextTheme);
	};

	return (
		<button
			aria-label="Toggle theme"
			className={className}
			onClick={toggleTheme}
			type="button"
		>
			<ContrastIcon className="size-6" />
		</button>
	);
}

export type HeaderProps = {
	brandName: string;
	currentPath: string;
	githubUrl: string;
	starCount?: number | string | null;
};

export function Header({
	brandName,
	currentPath,
	githubUrl,
	starCount,
}: HeaderProps) {
	const [scrolled, setScrolled] = useState(false);
	const [starHovered, setStarHovered] = useState(false);
	const [menuOpen, setMenuOpen] = useState(false);
	const reduceMotion = useReducedMotion();
	const menuId = useId();
	const animateLayout = !reduceMotion;
	const formattedStars =
		typeof starCount === "number"
			? new Intl.NumberFormat("en-US", { notation: "compact" }).format(
					starCount,
				)
			: starCount;

	useEffect(() => {
		const onScroll = () => setScrolled(window.scrollY > 24);
		onScroll();
		window.addEventListener("scroll", onScroll, { passive: true });
		return () => window.removeEventListener("scroll", onScroll);
	}, []);

	useEffect(() => {
		if (!menuOpen) return;
		const onKeyDown = (event: KeyboardEvent) => {
			if (event.key === "Escape") setMenuOpen(false);
		};
		const previousOverflow = document.body.style.overflow;
		document.body.style.overflow = "hidden";
		window.addEventListener("keydown", onKeyDown);
		return () => {
			document.body.style.overflow = previousOverflow;
			window.removeEventListener("keydown", onKeyDown);
		};
	}, [menuOpen]);

	const fade = { duration: 0.3, ease: "easeOut" } as const;
	const morphTransition = {
		scale: MORPH_SPRING,
		rotate: MORPH_SPRING,
		opacity: fade,
		filter: fade,
	} as const;
	const popTransition = {
		scale: POP_SPRING,
		rotate: POP_SPRING,
		opacity: fade,
		filter: fade,
	} as const;

	return (
		<div className="pointer-events-none fixed inset-x-0 top-5 z-50 flex justify-center px-5 sm:px-6 md:top-7.5">
			<motion.nav
				aria-label="Main navigation"
				className={join(
					"relative z-10 flex items-center",
					scrolled
						? "w-full max-w-3xl justify-between md:w-auto md:gap-2"
						: "w-full max-w-3xl justify-between",
				)}
				layout={animateLayout}
				transition={LAYOUT_SPRING}
			>
				<motion.div
					className="pointer-events-auto"
					layout={animateLayout}
					transition={LAYOUT_SPRING}
				>
					<a
						className={join(
							NAV_PILL,
							"flex h-12 items-center gap-2 px-4 focus-visible:outline-2 focus-visible:outline-white/70",
						)}
						href="/"
					>
						<TentUiMark className="h-5 w-auto text-(--hero-accent)" />
						<span className="font-semibold text-base text-white [font-family:var(--hero-font)]">
							{brandName}
						</span>
					</a>
				</motion.div>

				<motion.div
					className={join(
						NAV_PILL,
						"pointer-events-auto hidden h-12 items-center px-2 md:flex",
					)}
					layout={animateLayout}
					transition={LAYOUT_SPRING}
				>
					{NAV_LINKS.map((link, index) => (
						<Fragment key={link.href}>
							{index > 0 ? <span className="h-4 w-px bg-white/15" /> : null}
							<a
								aria-current={currentPath === link.href ? "page" : undefined}
								className={join(
									"rounded-full px-3.5 py-2 text-sm focus-visible:outline-2 focus-visible:outline-white/70",
									currentPath === link.href
										? "text-white"
										: "text-white/60 transition-colors duration-150 ease-out hover:text-white",
								)}
								href={link.href}
							>
								{link.label}
							</a>
						</Fragment>
					))}
				</motion.div>

				<motion.div
					className="pointer-events-auto hidden items-center gap-2 md:flex"
					layout={animateLayout}
					transition={LAYOUT_SPRING}
				>
					<a
						aria-label="GitHub"
						className={join(
							NAV_PILL,
							"flex h-12 items-center transition-colors duration-200 ease-out hover:bg-neutral-800 focus-visible:outline-2 focus-visible:outline-white/70",
						)}
						href={githubUrl}
						onBlur={() => setStarHovered(false)}
						onFocus={() => setStarHovered(true)}
						onMouseEnter={() => setStarHovered(true)}
						onMouseLeave={() => setStarHovered(false)}
						rel="noreferrer"
						target="_blank"
					>
						<span className="relative flex size-12 items-center justify-center">
							<motion.span
								animate={{
									scale: starHovered ? 0.25 : 1,
									opacity: starHovered ? 0 : 1,
									rotate: reduceMotion ? 0 : starHovered ? -60 : 0,
									filter: starHovered ? "blur(4px)" : "blur(0px)",
								}}
								className="flex items-center justify-center"
								initial={false}
								transition={reduceMotion ? { duration: 0 } : morphTransition}
							>
								<GithubIcon className="size-6 text-white" />
							</motion.span>
							<motion.span
								animate={{
									scale: starHovered ? 1 : 0.25,
									opacity: starHovered ? 1 : 0,
									rotate: reduceMotion ? 0 : starHovered ? 0 : -150,
									filter: starHovered ? "blur(0px)" : "blur(4px)",
								}}
								className="absolute inset-0 flex items-center justify-center text-(--hero-star)"
								initial={false}
								transition={
									reduceMotion
										? { duration: 0 }
										: starHovered
											? popTransition
											: morphTransition
								}
							>
								<StarIcon className="size-7" />
							</motion.span>
							<motion.span
								animate={{
									scale: starHovered && !reduceMotion ? 1 : 0,
									opacity: starHovered ? 1 : 0,
									rotate: reduceMotion ? 0 : starHovered ? 0 : -90,
								}}
								className="absolute top-2 right-2 text-(--hero-sparkle)"
								initial={false}
								transition={
									reduceMotion
										? { duration: 0 }
										: starHovered
											? {
													scale: { ...POP_SPRING, delay: 0.1 },
													rotate: { ...POP_SPRING, delay: 0.1 },
													opacity: { ...fade, delay: 0.1 },
												}
											: { duration: 0.15 }
								}
							>
								<SparkleIcon className="size-2" />
							</motion.span>
							<motion.span
								animate={{
									scale: starHovered && !reduceMotion ? 1 : 0,
									opacity: starHovered ? 1 : 0,
									rotate: reduceMotion ? 0 : starHovered ? 0 : 90,
								}}
								className="absolute bottom-2.5 left-2 text-(--hero-sparkle)"
								initial={false}
								transition={
									reduceMotion
										? { duration: 0 }
										: starHovered
											? {
													scale: { ...POP_SPRING, delay: 0.18 },
													rotate: { ...POP_SPRING, delay: 0.18 },
													opacity: { ...fade, delay: 0.18 },
												}
											: { duration: 0.15 }
								}
							>
								<SparkleIcon className="size-1.5" />
							</motion.span>
						</span>
						{formattedStars ? (
							<span className="pr-4 font-medium text-sm text-white/80 tabular-nums [font-family:var(--hero-font)]">
								{formattedStars}
							</span>
						) : null}
					</a>

					<ThemeButton
						className={join(
							NAV_PILL,
							"flex size-12 items-center justify-center text-white/80 transition-colors hover:bg-neutral-800 hover:text-white focus-visible:outline-2 focus-visible:outline-white/70",
						)}
					/>
				</motion.div>

				<motion.div
					className="pointer-events-auto md:hidden"
					layout={animateLayout}
					transition={LAYOUT_SPRING}
				>
					<button
						aria-controls={menuId}
						aria-expanded={menuOpen}
						aria-label={menuOpen ? "Close menu" : "Open menu"}
						className={join(
							NAV_PILL,
							"flex size-12 items-center justify-center focus-visible:outline-2 focus-visible:outline-white/70",
						)}
						onClick={() => setMenuOpen((open) => !open)}
						type="button"
					>
						<span className="flex h-4 w-5 flex-col justify-between">
							{[0, 1, 2].map((index) => (
								<motion.span
									animate={{
										rotate: menuOpen
											? index === 0
												? 45
												: index === 2
													? -45
													: 0
											: 0,
										y: menuOpen ? (index === 0 ? 7 : index === 2 ? -7 : 0) : 0,
										opacity: menuOpen && index === 1 ? 0 : 1,
									}}
									className="h-0.5 w-full bg-white"
									initial={false}
									key={index}
									transition={reduceMotion ? { duration: 0 } : MORPH_SPRING}
								/>
							))}
						</span>
					</button>
				</motion.div>
			</motion.nav>

			<AnimatePresence>
				{menuOpen ? (
					<motion.div
						animate={{ opacity: 1 }}
						className="pointer-events-auto fixed inset-0 z-0 bg-neutral-950/85 backdrop-blur-2xl md:hidden"
						exit={{ opacity: 0 }}
						id={menuId}
						initial={{ opacity: 0 }}
						transition={{
							duration: reduceMotion ? 0 : 0.25,
							ease: "easeOut",
						}}
					>
						<div className="flex h-full flex-col items-center justify-center gap-7 px-6">
							{NAV_LINKS.map((link, index) => (
								<motion.div
									animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
									exit={{ opacity: 0, y: 8, filter: "blur(6px)" }}
									initial={{ opacity: 0, y: 16, filter: "blur(8px)" }}
									key={link.href}
									transition={
										reduceMotion
											? { duration: 0 }
											: { ...POP_SPRING, delay: 0.06 + index * 0.06 }
									}
								>
									<a
										aria-current={
											currentPath === link.href ? "page" : undefined
										}
										className={join(
											"rounded-lg font-semibold text-3xl transition-colors duration-150 ease-out [font-family:var(--hero-font)] focus-visible:outline-2 focus-visible:outline-white/70",
											currentPath === link.href
												? "text-white"
												: "text-white/50 hover:text-white",
										)}
										href={link.href}
										onClick={() => setMenuOpen(false)}
									>
										{link.label}
									</a>
								</motion.div>
							))}

							<motion.div
								animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
								className="mt-3 flex items-center gap-2"
								exit={{ opacity: 0, y: 8, filter: "blur(6px)" }}
								initial={{ opacity: 0, y: 16, filter: "blur(8px)" }}
								transition={
									reduceMotion
										? { duration: 0 }
										: {
												...POP_SPRING,
												delay: 0.06 + NAV_LINKS.length * 0.06,
											}
								}
							>
								<a
									aria-label="GitHub"
									className={join(
										NAV_PILL,
										"flex size-12 items-center justify-center text-white focus-visible:outline-2 focus-visible:outline-white/70",
									)}
									href={githubUrl}
									rel="noreferrer"
									target="_blank"
								>
									<GithubIcon className="size-6" />
								</a>
								<ThemeButton
									className={join(
										NAV_PILL,
										"flex size-12 items-center justify-center text-white/80 focus-visible:outline-2 focus-visible:outline-white/70",
									)}
								/>
							</motion.div>
						</div>
					</motion.div>
				) : null}
			</AnimatePresence>
		</div>
	);
}

export default Header;

